using System.Text.Json;
using SboxNetworkStorage.Application.NetworkStorage.Endpoints;

namespace SboxNetworkStorage.Server.Tests.NetworkStorage;

/// <summary>
/// Asserts the native <see cref="EndpointStepExecutor"/> reproduces the
/// authoritative Bun <c>executeEndpoint</c> output (ok/status/body) for every
/// deterministic-subset fixture in the golden oracle
/// (endpoint-executor-oracle.json, generated by endpoint-executor-oracle.mjs in
/// dry-run mode with mocked reads).
///
/// Success bodies are compared in full. Error bodies compare status +
/// <c>error.code</c> + <c>error.message</c> + condition-rejection metadata;
/// the diagnostic <c>error.step</c>/<c>error.docsUrl</c> fields are not part of
/// the runtime contract and are normalized out.
/// </summary>
public sealed class EndpointStepExecutorParityTests
{
    private static readonly OracleCase[] Cases = LoadOracle();
    private static readonly DateTimeOffset FixedTime = DateTimeOffset.Parse("2026-06-10T00:00:00Z");

    [Fact]
    public void OracleFixture_IsNonTrivial()
    {
        Assert.True(Cases.Length >= 15, $"Expected >=15 executor-oracle cases, found {Cases.Length}.");
        Assert.Contains(Cases, c => c.Id == "condition_reject");
        Assert.Contains(Cases, c => c.Id == "read_mock_and_echo");
    }

    [Fact]
    public void EndpointStepExecutor_MatchesJsRuntime_ForEveryOracleCase()
    {
        var executor = new EndpointStepExecutor();
        var failures = new List<string>();

        foreach (var c in Cases)
        {
            var def = (Dictionary<string, object?>)EndpointExpression.FromJson(c.Def)!;
            var input = AsDict(EndpointExpression.FromJson(c.Request.GetProperty("input")));
            var gameValues = AsDict(EndpointExpression.FromJson(c.Request.GetProperty("gameValues")));
            var steamId = c.Request.GetProperty("steamId").GetString() ?? "";
            var mock = AsDict(EndpointExpression.FromJson(c.Request.GetProperty("mockData")));

            var request = new EndpointExecutionRequest(
                Input: input,
                SteamId: steamId,
                PlayerKey: steamId,
                GameValues: gameValues,
                ProjectId: "proj_oracle",
                UserId: "user_oracle",
                HasSecretKey: false,
                IsDedicatedServer: false,
                ExecTime: FixedTime,
                ReadRecord: (collection, _) => mock.TryGetValue(collection, out var rec) ? rec : null);

            EndpointExecutionResult result;
            try
            {
                result = executor.Execute(def, request);
            }
            catch (EndpointExecutionUnsupportedException ex)
            {
                failures.Add($"[{c.Id}] unexpectedly UNSUPPORTED: {ex.Message}");
                continue;
            }

            if (result.Ok != c.Ok) { failures.Add($"[{c.Id}] ok: expected {c.Ok}, got {result.Ok}"); continue; }
            if (result.Status != c.Status) { failures.Add($"[{c.Id}] status: expected {c.Status}, got {result.Status}"); continue; }

            var expectedBody = Normalize(ConvertJson(c.Body));
            var actualBody = Normalize(result.Body);
            if (!JsDeepEquals(actualBody, expectedBody))
                failures.Add($"[{c.Id}] body: expected {Json(c.Body)} got {Json(actualBody)}");
        }

        Assert.True(failures.Count == 0, $"{failures.Count}/{Cases.Length} executor parity mismatches:\n  " + string.Join("\n  ", failures));
    }

