    private static EndpointExecutionRequest MinimalRequest() => new(
        Input: new Dictionary<string, object?>(),
        SteamId: "76561198000000000",
        PlayerKey: "76561198000000000",
        GameValues: new Dictionary<string, object?>(),
        ProjectId: "p", UserId: "u",
        HasSecretKey: false, IsDedicatedServer: false,
        ExecTime: FixedTime,
        ReadRecord: (_, _) => null);

    // ── Normalization: drop diagnostic error.step/error.docsUrl ──

    private static object? Normalize(object? body)
    {
        if (body is not Dictionary<string, object?> dict) return body;
        if (!dict.TryGetValue("error", out var errRaw) || errRaw is not Dictionary<string, object?> err) return body;
        var clone = new Dictionary<string, object?>(dict);
        var errClone = new Dictionary<string, object?>(err);
        errClone.Remove("step");
        errClone.Remove("docsUrl");
        clone["error"] = errClone;
        return clone;
    }

    // ── Oracle loading ──

    private sealed record OracleCase(string Id, JsonElement Def, JsonElement Request, bool Ok, int Status, JsonElement Body);

    private static OracleCase[] LoadOracle()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "NetworkStorage", "endpoint-executor-oracle.json");
        using var doc = JsonDocument.Parse(File.ReadAllText(path));
        var list = new List<OracleCase>();
        foreach (var c in doc.RootElement.GetProperty("cases").EnumerateArray())
        {
            list.Add(new OracleCase(
                c.GetProperty("id").GetString()!,
                c.GetProperty("def").Clone(),
                c.GetProperty("request").Clone(),
                c.GetProperty("ok").GetBoolean(),
                c.GetProperty("status").GetInt32(),
                c.GetProperty("body").Clone()));
        }
        return list.ToArray();
    }

    private static object? ConvertJson(JsonElement el) => EndpointExpression.FromJson(el);

    private static Dictionary<string, object?> AsDict(object? v) => v as Dictionary<string, object?> ?? new Dictionary<string, object?>();

    private static string Json(object? v) => JsonSerializer.Serialize(v);

    private static bool JsDeepEquals(object? a, object? b)
    {
        if (EndpointExpression.IsNullish(a) || EndpointExpression.IsNullish(b))
            return EndpointExpression.IsNullish(a) && EndpointExpression.IsNullish(b);
        switch (a)
        {
            case double da when b is double db: return da == db || (double.IsNaN(da) && double.IsNaN(db));
            case bool ba when b is bool bb: return ba == bb;
            case string sa when b is string sb: return string.Equals(sa, sb, StringComparison.Ordinal);
            case List<object?> la when b is List<object?> lb:
                if (la.Count != lb.Count) return false;
                for (var i = 0; i < la.Count; i++) if (!JsDeepEquals(la[i], lb[i])) return false;
                return true;
            case Dictionary<string, object?> oa when b is Dictionary<string, object?> ob:
                if (oa.Count != ob.Count) return false;
                foreach (var (k, v) in oa) { if (!ob.TryGetValue(k, out var ov) || !JsDeepEquals(v, ov)) return false; }
                return true;
            default: return false;
        }
    }

    // ── Workflow step tests (async) ──

    [Fact]
    public async Task ExecuteAsync_WorkflowStep_LoadsAndExecutesSubSteps()
    {
        var executor = new EndpointStepExecutor();
        var workflowDef = new Dictionary<string, object?>
        {
            ["steps"] = new List<object?>
            {
                new Dictionary<string, object?> { ["id"] = "greeting", ["type"] = "transform", ["value"] = "Hello World" },
            }
        };

        var def = new Dictionary<string, object?>
        {
            ["steps"] = new List<object?>
            {
                new Dictionary<string, object?> { ["id"] = "wf", ["type"] = "workflow", ["workflow"] = "greet-wf" },
            },
            ["response"] = new Dictionary<string, object?> { ["body"] = new Dictionary<string, object?> { ["greeting"] = "{{wf.greeting}}" } }
        };

        var request = MinimalRequestAsync(loadWorkflow: (_, _) => Task.FromResult<Dictionary<string, object?>?>(workflowDef));
        var result = await executor.ExecuteAsync(def, request);
        Assert.True(result.Ok, $"Expected Ok but got Status={result.Status} Body={Serialize(result.Body)}");
        var body = result.Body as Dictionary<string, object?>;
        Assert.NotNull(body);
        Assert.Equal("Hello World", body.GetValueOrDefault("greeting"));
    }

