    // ── Webhook + sleep tests ──

    [Fact]
    public async Task ExecuteAsync_WebhookStep_SkipsInDryRunMode()
    {
        var executor = new EndpointStepExecutor();
        var def = new Dictionary<string, object?>
        {
            ["steps"] = new List<object?>
            {
                new Dictionary<string, object?> { ["id"] = "x", ["type"] = "transform", ["value"] = 1d },
                new Dictionary<string, object?>
                {
                    ["id"] = "wh", ["type"] = "webhook",
                    ["url"] = "https://discord.com/api/webhooks/123/abc",
                    ["title"] = "Test", ["description"] = "Hello"
                },
            },
            ["response"] = new Dictionary<string, object?> { ["body"] = new Dictionary<string, object?> { ["ok"] = true } }
        };

        var sent = false;
        var request = MinimalRequestAsync(
            skipWebhooks: true,
            executeWebhook: (_, _, _) => { sent = true; return Task.FromResult((true, 204, (string?)null)); });
        var result = await executor.ExecuteAsync(def, request);
        Assert.True(result.Ok, $"Expected Ok but got Status={result.Status} Body={Serialize(result.Body)}");
        Assert.False(sent, "Dry-run mode (_skipWebhooks) must NOT invoke the real webhook sender");
    }

