        var request = MinimalRequestAsync(
            skipWebhooks: false,
            executeWebhook: (url, _, _) => { sentUrl = url; return Task.FromResult((true, 204, (string?)null)); });
        var result = await executor.ExecuteAsync(def, request);
        Assert.True(result.Ok, $"Expected Ok but got Status={result.Status} Body={Serialize(result.Body)}");
        Assert.Equal("https://discord.com/api/webhooks/123/abc", sentUrl);
    }

    [Fact]
    public async Task ExecuteAsync_WebhookStep_InvalidUrl_ReturnsError()
    {
        var executor = new EndpointStepExecutor();
        var def = new Dictionary<string, object?>
        {
            ["steps"] = new List<object?>
            {
                new Dictionary<string, object?>
                {
                    ["id"] = "wh", ["type"] = "webhook",
                    ["url"] = "https://example.com/not-discord",
                    ["title"] = "Test"
                },
            }
        };

        var result = await executor.ExecuteAsync(def, MinimalRequestAsync());
        Assert.False(result.Ok, "Expected failure for non-Discord URL");
        Assert.Equal(400, result.Status);
    }

