    // ── Native-serve webhook-sender requirement (RequiresLiveWebhookSender) ──

    [Theory]
    [InlineData("webhook")]
    [InlineData("workflow")]
    public void RequiresLiveWebhookSender_DetectsWebhookCapableStep(string stepType)
    {
        var def = new Dictionary<string, object?>
        {
            ["steps"] = new List<object?>
            {
                new Dictionary<string, object?> { ["id"] = "r", ["type"] = "read", ["collection"] = "c" },
                new Dictionary<string, object?> { ["id"] = "x", ["type"] = stepType },
            }
        };
        Assert.True(EndpointStepExecutor.RequiresLiveWebhookSender(def));
    }

    [Theory]
    [InlineData("write")]
    [InlineData("delete")]
    public void RequiresLiveWebhookSender_RecordMutationStep_IsSafe(string stepType)
    {
        // Writes/deletes are flushed durably by the live-serve path, so they no longer
        // force a Bun fallback — only a potential webhook does.
        var def = new Dictionary<string, object?>
        {
            ["steps"] = new List<object?>
            {
                new Dictionary<string, object?> { ["id"] = "r", ["type"] = "read", ["collection"] = "c" },
                new Dictionary<string, object?> { ["id"] = "x", ["type"] = stepType, ["collection"] = "c" },
            }
        };
        Assert.False(EndpointStepExecutor.RequiresLiveWebhookSender(def));
    }

    [Fact]
    public void RequiresLiveWebhookSender_DetectsNestedWebhookInsideBlock()
    {
        var def = new Dictionary<string, object?>
        {
            ["steps"] = new List<object?>
