    [Fact]
    public void RequiresLiveWebhookSender_ReadOnlyEndpoint_IsSafe()
    {
        var def = new Dictionary<string, object?>
        {
            ["steps"] = new List<object?>
            {
                new Dictionary<string, object?> { ["id"] = "r", ["type"] = "read", ["collection"] = "c" },
                new Dictionary<string, object?> { ["id"] = "t", ["type"] = "transform", ["value"] = 1d },
                new Dictionary<string, object?> { ["id"] = "lb", ["type"] = "lookup", ["collection"] = "c2" },
            },
            ["response"] = new Dictionary<string, object?> { ["body"] = new Dictionary<string, object?> { ["ok"] = true } }
        };
        Assert.False(EndpointStepExecutor.RequiresLiveWebhookSender(def));
    }

    // ── Async test helpers ──

    private static EndpointExecutionRequest MinimalRequestAsync(
        IReadOnlyDictionary<string, object?>? input = null,
        Func<string, CancellationToken, Task<Dictionary<string, object?>?>>? loadWorkflow = null,
        bool skipWebhooks = false,
        Func<string, Dictionary<string, object?>, CancellationToken, Task<(bool Ok, int Status, string? Error)>>? executeWebhook = null) => new(
        Input: input ?? new Dictionary<string, object?>(),
        SteamId: "76561198000000000",
        PlayerKey: "76561198000000000",
        GameValues: new Dictionary<string, object?>(),
        ProjectId: "p", UserId: "u",
        HasSecretKey: false, IsDedicatedServer: false,
        ExecTime: FixedTime,
        ReadRecord: (_, _) => null,
        LoadWorkflow: loadWorkflow,
        ExecuteWebhookAsync: executeWebhook,
        SkipWebhooks: skipWebhooks);

    private static string Serialize(object? v) => JsonSerializer.Serialize(v);
}
